-- =====================================================================
--  payments_full.sql  --  self-contained: CREATE TABLEs + all INSERTs
--  Requires MySQL 8.0.16+ (for CHECK enforcement). Charset utf8mb4.
--  Run:  mysql -u <user> -p < payments_full.sql
-- =====================================================================

SET NAMES utf8mb4;
SET @OLD_FK=@@FOREIGN_KEY_CHECKS, @OLD_UQ=@@UNIQUE_CHECKS;
SET FOREIGN_KEY_CHECKS=0, UNIQUE_CHECKS=0;

-- ---------- SCHEMA ----------
-- =====================================================================
--  Payments / Reconciliation / Fraud dataset  --  MySQL schema (DDL)
-- ---------------------------------------------------------------------
--  Requires: MySQL 8.0.16+  (CHECK constraints are only ENFORCED there;
--            older versions parse but silently ignore them).
--  Charset : utf8mb4  (needed for the Rupee sign  and the  /  symbols
--            that appear in the data).
--
--  Load order is enforced by the foreign keys:
--    customers, merchants, benchmarks  ->  cards
--    -> gateway_transactions -> ledger_entries / chargebacks / fraud_flags
-- =====================================================================

CREATE DATABASE IF NOT EXISTS payments_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE payments_db;

-- Drop in reverse-dependency order so the script is re-runnable.
DROP TABLE IF EXISTS fraud_flags;
DROP TABLE IF EXISTS chargebacks;
DROP TABLE IF EXISTS ledger_entries;
DROP TABLE IF EXISTS gateway_transactions;
DROP TABLE IF EXISTS cards;
DROP TABLE IF EXISTS benchmarks;
DROP TABLE IF EXISTS merchants;
DROP TABLE IF EXISTS customers;


-- ---------------------------------------------------------------------
-- 1. customers
-- ---------------------------------------------------------------------
CREATE TABLE customers (
    customer_id     VARCHAR(12)   NOT NULL,
    onboarded_date  DATE          NOT NULL,
    home_city       VARCHAR(50)   NOT NULL,
    age_bucket      ENUM('18-24','25-34','35-44','45-54','55+') NOT NULL,
    kyc_tier        ENUM('Full KYC','Min KYC','Pending')        NOT NULL,
    risk_score      DECIMAL(5,2)  NOT NULL,
    CONSTRAINT pk_customers PRIMARY KEY (customer_id),
    CONSTRAINT chk_cust_risk CHECK (risk_score >= 0 AND risk_score <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 2. merchants
-- ---------------------------------------------------------------------
CREATE TABLE merchants (
    merchant_id     VARCHAR(12)   NOT NULL,
    merchant_name   VARCHAR(100)  NOT NULL,
    mcc_code        CHAR(4)       NOT NULL,          -- 4-digit ISO MCC (leading zeros preserved)
    category        ENUM('Food & Beverage','E-commerce','Travel','Fuel','Grocery',
                         'Utilities','Education','Healthcare','Entertainment',
                         'Gaming','Crypto/Forex','Money Transfer') NOT NULL,
    risk_class      ENUM('low','medium','high')      NOT NULL,
    onboarded_date  DATE          NOT NULL,
    city            VARCHAR(50)   NOT NULL,
    avg_ticket_inr  DECIMAL(12,2) NOT NULL,
    CONSTRAINT pk_merchants PRIMARY KEY (merchant_id),
    CONSTRAINT chk_merch_ticket CHECK (avg_ticket_inr >= 0),
    CONSTRAINT chk_merch_mcc    CHECK (mcc_code REGEXP '^[0-9]{4}$'),
    INDEX idx_merch_category (category),
    INDEX idx_merch_risk (risk_class)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 3. benchmarks  (reference / target KPIs — standalone table)
-- ---------------------------------------------------------------------
CREATE TABLE benchmarks (
    metric          VARCHAR(50)   NOT NULL,
    benchmark_value VARCHAR(30)   NOT NULL,          -- e.g. ' 99.5%', '0.8%  1.2%'
    CONSTRAINT pk_benchmarks PRIMARY KEY (metric)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 4. cards            (customer_id -> customers)
-- ---------------------------------------------------------------------
CREATE TABLE cards (
    card_id         VARCHAR(12)   NOT NULL,
    customer_id     VARCHAR(12)   NOT NULL,
    card_type       ENUM('Debit','Credit','Prepaid')    NOT NULL,
    card_network    ENUM('Visa','RuPay','Mastercard')   NOT NULL,
    issued_date     DATE          NOT NULL,
    is_active       TINYINT       NOT NULL DEFAULT 1,
    CONSTRAINT pk_cards PRIMARY KEY (card_id),
    CONSTRAINT chk_card_active CHECK (is_active IN (0,1)),
    CONSTRAINT fk_cards_customer
        FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    INDEX idx_cards_customer (customer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 5. gateway_transactions
--    customer_id -> customers,  merchant_id -> merchants
--    card_id     -> cards  (NULLABLE: UPI / NetBanking rows carry no card)
-- ---------------------------------------------------------------------
CREATE TABLE gateway_transactions (
    gateway_txn_id   VARCHAR(14)   NOT NULL,
    transaction_ts   DATETIME      NOT NULL,
    customer_id      VARCHAR(12)   NOT NULL,
    card_id          VARCHAR(12)   NULL,             -- NULL for UPI/NetBanking/Wallet
    merchant_id      VARCHAR(12)   NOT NULL,
    amount_inr       DECIMAL(12,2) NOT NULL,
    fee_inr          DECIMAL(12,2) NOT NULL,
    net_amount_inr   DECIMAL(12,2) NOT NULL,
    payment_method   ENUM('Debit Card','Credit Card','NetBanking','UPI','Wallet') NOT NULL,
    status           ENUM('SUCCESS','FAILED','PENDING') NOT NULL,
    transaction_city VARCHAR(50)   NOT NULL,
    is_fraud         TINYINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_gtx PRIMARY KEY (gateway_txn_id),
    CONSTRAINT chk_gtx_amount CHECK (amount_inr     >= 0),
    CONSTRAINT chk_gtx_fee    CHECK (fee_inr        >= 0),
    CONSTRAINT chk_gtx_net    CHECK (net_amount_inr >= 0),
    CONSTRAINT chk_gtx_fraud  CHECK (is_fraud IN (0,1)),
    CONSTRAINT fk_gtx_customer
        FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_gtx_merchant
        FOREIGN KEY (merchant_id) REFERENCES merchants (merchant_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_gtx_card
        FOREIGN KEY (card_id) REFERENCES cards (card_id)
        ON UPDATE CASCADE ON DELETE SET NULL,
    INDEX idx_gtx_customer (customer_id),
    INDEX idx_gtx_merchant (merchant_id),
    INDEX idx_gtx_card (card_id),
    INDEX idx_gtx_ts (transaction_ts),
    INDEX idx_gtx_status (status),
    INDEX idx_gtx_fraud (is_fraud)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 6. ledger_entries
--    customer_id -> customers,  merchant_id -> merchants
--    gateway_txn_id: SOFT link only (indexed, NOT a FK).
--    Reason: the dataset intentionally contains "ledger-only breaks"
--    (~80 rows with GTW99xxxxxxx ids that do NOT exist in the gateway
--    table). Enforcing a FK here would reject valid reconciliation-break
--    records, which the benchmarks table explicitly measures.
-- ---------------------------------------------------------------------
CREATE TABLE ledger_entries (
    ledger_id         VARCHAR(14)   NOT NULL,
    gateway_txn_id    VARCHAR(14)   NOT NULL,        -- soft FK to gateway_transactions
    settlement_ts     DATETIME      NOT NULL,
    customer_id       VARCHAR(12)   NOT NULL,
    merchant_id       VARCHAR(12)   NOT NULL,
    gross_amount_inr  DECIMAL(12,2) NOT NULL,
    fee_inr           DECIMAL(12,2) NOT NULL,
    net_amount_inr    DECIMAL(12,2) NOT NULL,
    gst_inr           DECIMAL(12,2) NOT NULL,
    settlement_status ENUM('SETTLED','PENDING','FAILED','REVERSED') NOT NULL,
    CONSTRAINT pk_ledger PRIMARY KEY (ledger_id),
    CONSTRAINT uq_ledger_gtx UNIQUE (gateway_txn_id),   -- one ledger row per txn
    CONSTRAINT chk_led_gross CHECK (gross_amount_inr >= 0),
    CONSTRAINT chk_led_fee   CHECK (fee_inr          >= 0),
    CONSTRAINT chk_led_net   CHECK (net_amount_inr   >= 0),
    CONSTRAINT chk_led_gst   CHECK (gst_inr          >= 0),
    CONSTRAINT fk_led_customer
        FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_led_merchant
        FOREIGN KEY (merchant_id) REFERENCES merchants (merchant_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    INDEX idx_led_gtx (gateway_txn_id),
    INDEX idx_led_customer (customer_id),
    INDEX idx_led_merchant (merchant_id),
    INDEX idx_led_ts (settlement_ts)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 7. chargebacks       (gateway_txn_id -> gateway_transactions)
-- ---------------------------------------------------------------------
CREATE TABLE chargebacks (
    chargeback_id   VARCHAR(10)   NOT NULL,
    gateway_txn_id  VARCHAR(14)   NOT NULL,
    reason_code     ENUM('Card Not Present','Fraudulent Transaction','Identity Theft',
                         'Unauthorized Charge','Quality Dispute','Service Not Provided',
                         'Refund Not Processed','Duplicate Charge') NOT NULL,
    amount_inr      DECIMAL(12,2) NOT NULL,
    raised_date     DATE          NOT NULL,
    status          ENUM('Pending','Disputed','Approved') NOT NULL,
    CONSTRAINT pk_chargebacks PRIMARY KEY (chargeback_id),
    CONSTRAINT uq_cb_gtx UNIQUE (gateway_txn_id),       -- one chargeback per txn
    CONSTRAINT chk_cb_amount CHECK (amount_inr >= 0),
    CONSTRAINT fk_cb_gtx
        FOREIGN KEY (gateway_txn_id) REFERENCES gateway_transactions (gateway_txn_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    INDEX idx_cb_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- 8. fraud_flags       (gateway_txn_id -> gateway_transactions)
-- ---------------------------------------------------------------------
CREATE TABLE fraud_flags (
    flag_id          VARCHAR(12)   NOT NULL,
    gateway_txn_id   VARCHAR(14)   NOT NULL,
    fraud_type       ENUM('amount_anomaly','velocity','geo_mismatch') NOT NULL,
    detection_reason VARCHAR(255)  NOT NULL,
    flagged_ts       DATE          NOT NULL,
    review_status    ENUM('Open','Confirmed Fraud','Reviewed','False Positive') NOT NULL,
    CONSTRAINT pk_fraud_flags PRIMARY KEY (flag_id),
    CONSTRAINT uq_ff_gtx UNIQUE (gateway_txn_id),       -- one flag per txn
    CONSTRAINT fk_ff_gtx
        FOREIGN KEY (gateway_txn_id) REFERENCES gateway_transactions (gateway_txn_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    INDEX idx_ff_type (fraud_type),
    INDEX idx_ff_review (review_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

USE payments_db;

-- ---------- DATA ----------

-- customers: 5000 rows

-- merchants: 551 rows

-- benchmarks: 10 rows

-- cards: 6073 rows

-- gateway_transactions: 70408 rows

-- ledger_entries: 66087 rows

-- chargebacks: 135 rows

-- fraud_flags: 303 rows

SET FOREIGN_KEY_CHECKS=@OLD_FK, UNIQUE_CHECKS=@OLD_UQ;

-- row-count sanity check
SELECT 'customers' t,COUNT(*) n FROM customers UNION ALL SELECT 'merchants',COUNT(*) FROM merchants UNION ALL SELECT 'benchmarks',COUNT(*) FROM benchmarks UNION ALL SELECT 'cards',COUNT(*) FROM cards UNION ALL SELECT 'gateway_transactions',COUNT(*) FROM gateway_transactions UNION ALL SELECT 'ledger_entries',COUNT(*) FROM ledger_entries UNION ALL SELECT 'chargebacks',COUNT(*) FROM chargebacks UNION ALL SELECT 'fraud_flags',COUNT(*) FROM fraud_flags;
